 IEnumerator Start(){folder=Path.GetFullPath("Logs/TruckSports/EssentialRelease/Terrier/"+mode);Directory.CreateDirectory(folder);File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("o"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<TerrierMatch>("TruckTerrierRacing");yield return null;m=FindAnyObjectByType<TerrierMatch>();
 for(int test=0;test<2;test++){yield return Fresh();for(int i=1;i<12;i++)m.racers[i].Wreck();m.enabled=false;foreach(var h in m.course.hurdles)h.gameObject.SetActive(false);for(int i=0;i<m.course.ramps.Length;i++)m.course.ramps[i].gameObject.SetActive(test==0&&i==1);var r=m.racers[0];var b=r.truck.body;b.position=m.course.World(new Vector3(0,.48f,test==0?35:65));b.rotation=m.course.DrivingRotation;b.linearVelocity=m.course.Forward*18;b.angularVelocity=Vector3.zero;Physics.SyncTransforms();manual=true;yield return new WaitForSeconds(.08f);if(test==1)Check(r.Jump(true),"grounded jump uses actual truck");float end=Time.fixedTime+2.5f,air=0,omega=0,tilt=0,min=999,max=0,start=Vector3.Dot(b.linearVelocity,m.course.Forward);
