 report.AppendLine("PHYSICS "+(test==0?"ramp":"jump")+" start="+start+" air="+air+" minForward="+min+" maxForward="+max+" maxTilt="+tilt+" maxOmega="+omega+" final="+b.linearVelocity+" damping="+b.linearDamping+"/"+b.angularDamping);Check(air>.15f,"actual airborne trajectory sampled");if(mode!="baseline"){Check(tilt<70,"ordinary takeoff stays controllably upright");Check(min>start*.8f,"flight preserves forward momentum");}manual=false;foreach(var h in m.course.hurdles)h.gameObject.SetActive(true);foreach(var ramp in m.course.ramps)ramp.gameObject.SetActive(true);m.enabled=true;m.SetupScreen();yield return null;}
 if(mode=="full"){yield return Fresh();Check(m.course.HalfWidth(m.course.Length*.6f)>33.9f,"majority of track remains broad");float last=0;foreach(var h in m.course.hurdles)last=Mathf.Max(last,h.localPosition.z);Check(m.course.HalfWidth(last)>33.9f&&m.course.HalfWidth(m.course.Length)<3.1f,"funnel begins after last ordinary wall");m.SetupScreen();m.AllBots();foreach(var p in m.setup.players)p.difficulty=BowlingDifficulty.Hard;tally=new SportsScoreAcceptance.Tally(m);bool awardCaptured=false;Check(m.StartMatch(),"full twelve-truck Hard competition starts");Time.timeScale=3;float end=Time.realtimeSinceStartup+1000,next=0;int heat=-1,legal=0;bool captured=false;
 while(!m.Finished&&Time.realtimeSinceStartup<end){if(!awardCaptured&&m.ScoreJournal.Count>0){yield return SportsScoreAcceptance.CaptureAward(m,Check,folder);awardCaptured=true;}if(m.Heat!=heat){heat=m.Heat;report.AppendLine("HEAT "+heat+" length="+m.course.Length+" layout="+m.course.LayoutHash);Write();}if(m.HeatWinner>=0&&m.Phase==TerrierPhase.Race)legal++;if(!captured&&m.Phase==TerrierPhase.Race&&m.HeatTime>3){captured=true;SportsControlledCapture.Save(m,1280,720,folder+"/broadcast-720.png");SportsControlledCapture.Save(m,1920,1080,folder+"/broadcast-1080.png");}if(Time.realtimeSinceStartup>next){next=Time.realtimeSinceStartup+3;File.WriteAllText(folder+"/live.txt","heat="+m.Heat+" phase="+m.Phase+" time="+m.HeatTime+" wins="+string.Join(",",m.wins));}yield return null;}Time.timeScale=1;tally.Verify(slot=>m.wins[slot],Check);Check(awardCaptured,"actual first legal heat-win award captured");if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,m.ResultPlace,slot=>(double?)m.wins[slot],slot=>m.MatchWinner==slot);
 Check(m.Finished&&m.MatchWinner>=0&&m.wins[m.MatchWinner]==5,"physical twelve-truck match reaches first-to-five");Check(legal>0,"legal complete-body finishes observed");report.AppendLine("MATCH heats="+m.Heat+" locks="+m.Locks+" winner="+m.MatchWinner+" wins="+string.Join(",",m.wins));m.SetupScreen();Check(m.StartMatch()&&m.Heat==1&&m.Locks==0&&m.MatchWinner<0&&m.ScoreJournal.Count==0,"rematch clears scores, finish locks and score journal");m.Pause();float clock=m.HeatTime;var pos=m.racers[0].truck.body.position;yield return new WaitForSecondsRealtime(.2f);Check(m.HeatTime==clock&&m.racers[0].truck.body.position==pos,"pause preserves truck pose and clock");m.Resume();m.SetupScreen();}
 if(mode=="views"){yield return Views();yield return CompactViews();}
 SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<TerrierMatch>()==null,"menu releases scene authority");report.AppendLine("CHECKS="+checks+" ERRORS="+errors+". Platform="+Application.platform+"; controlled takeoff poses/velocities, actual NWH/PhysX, autonomous AI and software input devices. No human or physical-hardware claim.");File.WriteAllText(folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;
