 Application.Quit(errors==0?0:2);}
 IEnumerator Views(){var catalog=m.course.weather.presets;Check(catalog!=null,"shared installed weather catalog is bound");foreach(string weather in new[]{"Clear","Blizzard"}){var entry=Array.Find(catalog.entries,e=>e.displayName==weather);Check(entry!=null,"actual installed weather preset "+weather);catalog.Select(entry.id);yield return Fresh();float end=Time.realtimeSinceStartup+8;while(m.HeatTime<3&&Time.realtimeSinceStartup<end)yield return null;Time.timeScale=0;foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1280,960),new Vector2Int(2560,1080)})SportsControlledCapture.Save(m,size.x,size.y,folder+"/"+weather+"-"+size.x+"x"+size.y+".png");Check(m.course.weather.PresetId==entry.id,"selected weather remains authoritative through racing "+weather);Time.timeScale=1;m.SetupScreen();}catalog.Select(Array.Find(catalog.entries,e=>e.displayName=="Clear").id);yield return Fresh();yield return new WaitForSeconds(1.3f);Time.timeScale=0;var camera=m.broadcast.view;var position=camera.transform.position;var rotation=camera.transform.rotation;m.broadcast.Pose(m.dessert.basin.position+Vector3.up*5,m.course.Heading*new Vector3(100,110,-165),62,true);SportsControlledCapture.Save(m,1920,1080,folder+"/actual-cherry-dessert-1080.png");camera.transform.SetPositionAndRotation(position,rotation);Time.timeScale=1;m.SetupScreen();SportsCameraOptions.Set(true);m.option=0;m.AllBots();Check(m.StartMatch()&&m.cameras.Length==4,"optional four AI cab views retain four unique cameras");yield return new WaitForSeconds(4.5f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)})SportsControlledCapture.Save(m,size.x,size.y,folder+"/four-cabs-"+size.x+"x"+size.y+".png");m.SetupScreen();yield return new WaitForSecondsRealtime(.3f);SportsControlledCapture.Save(m,1920,1080,folder+"/weather-setup-1080.png");}
 IEnumerator CompactViews(){
  var pads=new Gamepad[4];var background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
  softwareViews=true;
  try{
   for(int i=0;i<4;i++){pads[i]=InputSystem.AddDevice<Gamepad>();InputSystem.EnableDevice(pads[i]);}
   for(int pass=0;pass<5;pass++){
    int humans=pass==4?1:pass+1;bool ai=pass==4;freezeSoftwareFrames=false;Time.timeScale=1;m.SetupScreen();m.AllBots();m.option=0;SportsCameraOptions.Set(ai);foreach(var preset in m.course.weather.presets.entries)if(preset.displayName=="Clear"){m.course.weather.presets.Select(preset.id);break;}
    for(int i=0;i<humans;i++){m.setup.players[i].source=BowlingSource.WholeController;m.setup.players[i].pad=pads[i];}
    Check(m.StartMatch(),"compact human cab setup starts humans="+humans+" AI views="+ai);yield return new WaitForSecondsRealtime(3.3f);Check(m.Running&&!m.Paused,"compact software participants stay connected humans="+humans+" devicesReady="+m.DevicesReady+" phase="+m.Phase);freezeSoftwareFrames=true;Time.timeScale=0;
    Check(m.cameras.Length==(ai?4:humans),"compact HUD follows actual selected view count");
    foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){
     Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.4f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();Check(Application.isEditor||Screen.width==size.x&&Screen.height==size.y,"actual Windows compact HUD resolution "+size);
     bool valid=true;var occupied=new Rect[m.cameras.Length];
     for(int view=0;view<m.cameras.Length;view++){
      var card=m.menus.viewPanels[view].Find("Compact owned viewport score") as RectTransform;if(card==null||!card.gameObject.activeInHierarchy){valid=false;continue;}var corners=new Vector3[4];card.GetWorldCorners(corners);var low=RectTransformUtility.WorldToScreenPoint(null,corners[0]);var high=RectTransformUtility.WorldToScreenPoint(null,corners[2]);occupied[view]=Rect.MinMaxRect(low.x,low.y,high.x,high.y);var r=m.cameras[view].rect;int owner=m.viewSlots[view];
      valid&=low.x>=r.xMin*Screen.width-1&&high.x<=r.xMax*Screen.width+1&&low.y>=r.yMin*Screen.height-1&&high.y<=r.yMax*Screen.height+1&&!m.menus.viewTexts[view].gameObject.activeSelf&&card.Find("Participant name").GetComponent<TMPro.TMP_Text>().text==m.setup.players[owner].name&&card.Find("Owned score").GetComponent<TMPro.TMP_Text>().text==m.wins[owner]+" / 5";
      for(int other=0;other<view;other++)valid&=!occupied[view].Overlaps(occupied[other]);
     }
     Check(valid,"one correctly attributed, screen-safe compact group per viewport humans="+humans+" AI="+ai+" size="+size);
     string path=folder+"/compact-"+humans+"-human-ai-"+ai+"-"+size.x+".png";if(Application.isEditor)SportsControlledCapture.Save(m,size.x,size.y,path);else{ScreenCapture.CaptureScreenshot(path);yield return new WaitForSecondsRealtime(.2f);}
    }
   }
  }finally{softwareViews=freezeSoftwareFrames=false;Time.timeScale=1;m.SetupScreen();foreach(var pad in pads)if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);InputSystem.settings.backgroundBehavior=background;}
 }
